525→  // After page.reload(), Zustand store is empty. The app must
526→  // re-authenticate, re-sync root metadata from IPNS, and then
527→  // cold-load subfolder contents via navigateTo (IPNS resolve +
528→  // key unwrapping). This path is NOT exercised by in-session tests.
529→
530→  test('3.7 Page reload preserves session and reloads root folder', async () => {
531→    // On staging, IPNS resolution after a page reload can take >60s due to
532→    // cache propagation delays. Allow generous timeout with a retry cycle.
533→    test.setTimeout(240000);
534→
535→    // Navigate to root before reload so we start from a clean state
536→    await navigateToRoot();
537→
538→    // Reload the page — Zustand store is wiped
539→    await page.reload({ waitUntil: 'domcontentloaded' });
540→
541→    // Reset navigation stack since we're starting fresh
542→    navigationStack.length = 0;
543→    navigationStack.push('root');
544→
545→    // Core Kit session auto-restores after reload (real wallet login persists).
546→    // This involves Core Kit init from localStorage + exportTssKey (4-10s on
547→    // Sapphire Devnet) + token refresh + vault load + SDK init.
548→    // Use generous timeout as Sapphire Devnet latency varies.
549→    await page.locator('[data-testid="user-menu"]').waitFor({
550→      state: 'visible',
551→      timeout: 120000,
552→    });
553→
554→    // Wait for vault + SDK to be fully initialized after session restore.
555→    // Without this, navigating into subfolders may fail because the SDK client
556→    // isn't ready to decrypt subfolder IPNS records.
557→    await page.waitForFunction(
558→      () => {
559→        const stores = (
560→          window as unknown as Record<
561→            string,
562→            Record<string, { getState: () => Record<string, unknown> }>
563→          >
564→        ).__ZUSTAND_STORES;
565→        if (!stores?.vault) return false;
566→        const vault = stores.vault.getState();
567→        return !!vault.rootFolderKey && !!vault.rootIpnsKeypair && !!vault.rootIpnsName;
568→      },
569→      { timeout: 60_000 }
570→    );
571→
572→    // Wait for initial sync to complete — all root items must appear.
573→    // This proves IPNS root metadata was re-fetched and decrypted.
574→    // Use 120s timeout — staging IPNS resolution can exceed 60s.
575→    await fileList.waitForItemToAppear(workspaceFolder, { timeout: 120000 });
576→
577→    // Wait for files to appear too (sync may render folders before files)
578→    await fileList.waitForItemToAppear(rootFiles[0].name, { timeout: 30000 });
579→
580→    // Verify other root-level items are also visible
581→    // rootFiles[0] was moved to workspace in 5.1 — but Phase 5 hasn't run yet at this point
582→    for (const file of rootFiles) {
583→      expect(await fileList.isItemVisible(file.name)).toBe(true);
584→    }
585→    expect(await fileList.isItemVisible(editableFileName)).toBe(true);
586→  });
587→
