  2→import type { PrivateKeyAccount } from 'viem/accounts';
  3→import { createTestAccount, setupMockWallet, loginViaWallet } from '../utils/wallet-login-helpers';
  4→import { createTestTextFile, cleanupTestFiles } from '../utils/test-files';
  5→import { bumpServerSequence } from '../utils/conflict-helpers';
  6→import { FileListPage } from '../page-objects/file-browser/file-list.page';
  7→import { UploadZonePage } from '../page-objects/file-browser/upload-zone.page';
  8→import { CreateFolderDialogPage } from '../page-objects/dialogs/create-folder-dialog.page';
  9→import { ContextMenuPage } from '../page-objects/file-browser/context-menu.page';
 10→import { ConfirmDialogPage } from '../page-objects/dialogs/confirm-dialog.page';
 11→import { TextEditorDialogPage } from '../page-objects/dialogs/text-editor-dialog.page';
 12→
 13→/**
 14→ * Conflict Detection E2E Test Suite
 15→ *
 16→ * Verifies the full conflict detection flow end-to-end:
 17→ * 1. Server-side sequence is bumped (simulating another device publishing)
 18→ * 2. Web client detects 409 on its next folder publish
 19→ * 3. Client re-syncs (fetches latest remote state)
 20→ * 4. Client retries the operation with the fresh sequence
 21→ * 5. User's operation succeeds and the item appears in the file list
 22→ *
 23→ * Tests cover:
 24→ * - Upload file with stale folder sequence -> auto re-sync -> file visible
 25→ * - Create folder with stale parent sequence -> auto re-sync -> folder visible
 26→ * - Per-file IPNS publish (content update) does NOT trigger conflict detection
 27→ *
 28→ * Depends on:
 29→ * - Plan 16-01: API accepts expectedSequenceNumber, returns 409 on mismatch
 30→ * - Plan 16-02: Web client sends expectedSequenceNumber and handles 409 with re-sync + retry
 31→ */
 32→test.describe.serial('Conflict Detection', () => {
 33→  let browser: Browser;
 34→  let context: BrowserContext;
 35→  let page: Page;
 36→
 37→  // Page objects (initialized after login)
 38→  let fileList: FileListPage;
 39→  let uploadZone: UploadZonePage;
 40→  let createFolderDialog: CreateFolderDialogPage;
 41→  let contextMenu: ContextMenuPage;
 42→  let confirmDialog: ConfirmDialogPage;
 43→  let textEditorDialog: TextEditorDialogPage;
 44→
 45→  let account: PrivateKeyAccount;
 46→
 47→  // Auth state -- extracted from browser after wallet login
 48→  let accessToken = '';
 49→  let rootIpnsName = '';
 50→
 51→  const apiBaseUrl = process.env.API_BASE_URL || 'http://localhost:3000';
 52→
 53→  // Unique suffix per test run to avoid naming collisions
 54→  const runId = Date.now().toString();
 55→
 56→  // Cleanup: track items created during tests for deletion
 57→  const createdItems: Array<{ name: string; type: 'file' | 'folder' }> = [];
 58→
 59→  test.beforeAll(async ({ browser: testBrowser }) => {
 60→    test.setTimeout(90_000); // Core Kit init + SIWE can be slow
 61→    browser = testBrowser;
 62→    context = await browser.newContext();
 63→    page = await context.newPage();
 64→
 65→    // Generate a random wallet identity and install mock wallet
 66→    account = createTestAccount();
 67→    await setupMockWallet(page, account);
 68→
 69→    // Initialize page objects
 70→    fileList = new FileListPage(page);
 71→    uploadZone = new UploadZonePage(page);
 72→    createFolderDialog = new CreateFolderDialogPage(page);
 73→    contextMenu = new ContextMenuPage(page);
 74→    confirmDialog = new ConfirmDialogPage(page);
 75→    textEditorDialog = new TextEditorDialogPage(page);
 76→
 77→    // Login via wallet (mock wallet auto-approves connect + SIWE)
 78→    await loginViaWallet(page, { timeout: 60_000 });
 79→
 80→    // Extract auth state from Zustand stores for bumpServerSequence API calls
 81→    const authData = await page.evaluate(() => {
 82→      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
 83→        auth: { getState: () => { accessToken: string } };
 84→        vault: { getState: () => { rootIpnsName: string } };
 85→      };
 86→      return {
 87→        accessToken: stores.auth.getState().accessToken,
 88→        rootIpnsName: stores.vault.getState().rootIpnsName,
 89→      };
 90→    });
 91→    accessToken = authData.accessToken;
 92→    rootIpnsName = authData.rootIpnsName;
 93→
 94→    // Verify we're on the files page and the vault is accessible.
 95→    // Wait for either the file list grid (non-empty folder) or empty state (fresh vault).
 96→    await page.waitForURL('**/files', { timeout: 60000 });
 97→    await Promise.race([
 98→      fileList.fileListContainer().waitFor({ state: 'visible', timeout: 30000 }),
 99→      page.locator('[data-testid="empty-state"]').waitFor({ state: 'visible', timeout: 30000 }),
100→    ]);
101→
102→    // Seed: upload a file to ensure the root folder IPNS record exists.
103→    // For a fresh vault, no IPNS record is published until the first mutation.
104→    // bumpServerSequence needs an existing record to resolve, so we bootstrap here.
105→    const seedFileName = `seed-${runId}.txt`;
106→    const seedFile = createTestTextFile(seedFileName, 'seed file for conflict tests');
107→    await uploadZone.uploadFile(seedFile.path);
108→    await fileList.waitForItemToAppear(seedFileName, { timeout: 60000 });
109→    createdItems.push({ name: seedFileName, type: 'file' });
110→  });
111→
112→  test.afterAll(async () => {
113→    test.setTimeout(60_000); // Cleanup can be slow with rate-limited API
114→    // Clean up remote items created during tests (runs even if earlier serial tests fail)
115→    try {
116→      const itemsToDelete = [...createdItems].reverse();
117→      for (const item of itemsToDelete) {
118→        const isVisible = await fileList.isItemVisible(item.name).catch(() => false);
119→        if (!isVisible) continue;
120→
121→        await fileList.rightClickItem(item.name);
122→        await contextMenu.waitForOpen();
123→        await contextMenu.clickDelete();
124→        await confirmDialog.waitForOpen();
125→        await confirmDialog.clickConfirm();
126→        await fileList.waitForItemToDisappear(item.name, { timeout: 30000 });
127→      }
128→    } catch (err) {
129→      // Best-effort cleanup -- don't fail the suite if cleanup itself fails
130→      console.warn('Cleanup of conflict test items failed:', err);
131→    }
132→
133→    cleanupTestFiles();
134→    if (context) {
135→      await context.close();
136→    }
137→  });
138→
139→  // ============================================================
140→  // Helper: Get current access token from Zustand auth store
141→  // ============================================================
142→
143→  /**
144→   * Get a fresh access token from the browser's Zustand auth store.
145→   * The token may be refreshed between tests.
146→   */
147→  async function getAccessToken(): Promise<string> {
148→    // Always read from the live Zustand store to get the freshest token
149→    // (tokens may be refreshed between tests)
150→    const liveToken = await page.evaluate(() => {
151→      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
152→        auth: { getState: () => { accessToken: string } };
153→      };
154→      return stores?.auth?.getState()?.accessToken ?? '';
155→    });
156→    if (liveToken) return liveToken;
157→    // Fallback: use token captured during beforeAll
158→    return accessToken;
159→  }
160→
161→  /**
162→   * Get the root IPNS name from the browser's Zustand vault store.
163→   */
164→  async function getRootIpnsName(): Promise<string> {
165→    const liveName = await page.evaluate(() => {
166→      const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
167→        vault: { getState: () => { rootIpnsName: string } };
168→      };
169→      return stores?.vault?.getState()?.rootIpnsName ?? '';
170→    });
171→    if (liveName) return liveName;
172→    return rootIpnsName;
173→  }
174→
175→  // ============================================================
176→  // Test 1: Upload file with stale sequence -> conflict -> retry
177→  // ============================================================
178→
179→  test('upload file to root when sequence is stale -> conflict auto-resolved -> file appears', async () => {
180→    test.slow(); // Allow extra time for conflict re-sync cycle
181→
182→    const fileName = `conflict-upload-${runId}.txt`;
183→
184→    // Step 1: Bump the server-side sequence number so the client's local
185→    // sequence becomes stale. This simulates another device publishing.
186→    const accessToken = await getAccessToken();
187→    const rootIpnsName = await getRootIpnsName();
188→
189→    expect(accessToken).toBeTruthy();
190→    expect(rootIpnsName).toBeTruthy();
191→
192→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
193→
194→    // Step 2: Upload a test file via the upload zone.
195→    // The client will:
196→    // - Encrypt the file content and upload to IPFS
197→    // - Build the new folder metadata (with the new file added)
198→    // - Publish the folder IPNS record with its (now-stale) expectedSequenceNumber
199→    // - Receive a 409 Conflict response from the API
200→    // - Re-sync: fetch the latest folder metadata from IPNS
201→    // - Retry the upload with the fresh sequence number
202→    // - Succeed on retry
203→    const testFile = createTestTextFile(fileName, `Conflict detection test file - ${runId}`);
204→    await uploadZone.uploadFile(testFile.path);
205→
206→    // Step 3: Assert the file appears in the file list despite the initial
207→    // conflict. Use a generous timeout to allow for the re-sync cycle.
208→    await fileList.waitForItemToAppear(fileName, { timeout: 60000 });
209→
210→    // Step 4: Assert the operation completed successfully (no persistent error).
211→    // The upload zone should not show an error after conflict auto-resolution.
212→    const hasUploadError = await uploadZone.hasError();
213→    expect(hasUploadError).toBe(false);
214→
215→    // Track for cleanup
216→    createdItems.push({ name: fileName, type: 'file' });
217→  });
218→
219→  // ============================================================
220→  // Test 2: Create folder with stale sequence -> conflict -> retry
221→  // ============================================================
222→
223→  test('create folder when parent sequence is stale -> conflict auto-resolved -> folder appears', async () => {
224→    test.slow(); // Allow extra time for conflict re-sync cycle
225→
226→    const folderName = `conflict-folder-${runId}`;
227→
228→    // Step 1: Bump the server-side sequence number again.
229→    const accessToken = await getAccessToken();
230→    const rootIpnsName = await getRootIpnsName();
231→
232→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
233→
234→    // Step 2: Create a folder via the new-folder button.
235→    // The client will hit the same 409 -> re-sync -> retry flow.
236→    const newFolderButton = page.locator('.file-browser-new-folder-button');
237→    await newFolderButton.click();
238→    await createFolderDialog.waitForOpen();
239→    await createFolderDialog.createFolder(folderName);
240→
241→    // Step 3: Assert the folder appears in the file list.
242→    await fileList.waitForItemToAppear(folderName, { timeout: 60000 });
243→
244→    // Step 4: Verify no persistent error state after conflict auto-resolution.
245→    const folderVisible = await fileList.isItemVisible(folderName);
246→    expect(folderVisible).toBe(true);
247→
248→    // Track for cleanup
249→    createdItems.push({ name: folderName, type: 'folder' });
250→  });
251→
252→  // ============================================================
253→  // Test 3 (negative): Per-file IPNS publish does NOT conflict
254→  // ============================================================
255→
256→  test('per-file IPNS content update does not trigger conflict even with stale folder sequence', async () => {
257→    test.slow(); // Allow for file edit + save cycle
258→
259→    // Step 1: Upload a text file to edit later.
260→    // This resets/syncs the root folder sequence as a side effect of the
261→    // successful publish from Test 2.
262→    const editFileName = `conflict-edit-target-${runId}.txt`;
263→    const originalContent = `Original content for conflict edit test - ${runId}`;
264→    const updatedContent = `Updated content via text editor - ${runId} - modified`;
265→
266→    const testFile = createTestTextFile(editFileName, originalContent);
267→    await uploadZone.uploadFile(testFile.path);
268→    await fileList.waitForItemToAppear(editFileName, { timeout: 30000 });
269→
270→    // Step 2: Bump the folder's server-side sequence number.
271→    // This makes the client's local folder sequence stale.
272→    // Brief pause to avoid API rate limiting (10 req/s) from rapid test transitions.
273→    await page.waitForTimeout(2000);
274→    const accessToken = await getAccessToken();
275→    const rootIpnsName = await getRootIpnsName();
276→
277→    await bumpServerSequence({ page, apiBaseUrl, accessToken, rootIpnsName });
278→
279→    // Step 3: Open the text editor for the file and save new content.
280→    // The text editor save flow calls handleUpdateFile, which publishes only
281→    // the per-file IPNS record (NOT the folder IPNS record). Per the Phase 16
282→    // design, per-file IPNS publishes use last-write-wins with no
283→    // expectedSequenceNumber, so they never trigger conflict detection.
284→    await fileList.rightClickItem(editFileName);
285→    await contextMenu.waitForOpen();
286→    await contextMenu.clickEdit();
287→
288→    await textEditorDialog.waitForOpen({ timeout: 15000 });
289→    await textEditorDialog.waitForContentLoaded({ timeout: 15000 });
290→    await textEditorDialog.setContent(updatedContent);
291→    await textEditorDialog.clickSave();
292→    await textEditorDialog.waitForClose({ timeout: 30000 });
293→
294→    // Step 4: Assert the file update completed without a persistent error.
295→    // The file should still be visible in the list (not removed by an error).
296→    await fileList.waitForItemToAppear(editFileName, { timeout: 15000 });
297→    const fileVisible = await fileList.isItemVisible(editFileName);
298→    expect(fileVisible).toBe(true);
299→
300→    // Step 5: Verify no upload-zone error state.
301→    const hasUploadError = await uploadZone.hasError();
302→    expect(hasUploadError).toBe(false);
303→
304→    // Track for cleanup
305→    createdItems.push({ name: editFileName, type: 'file' });
306→  });
307→});
