 175→  /**
 176→   * Navigate into a folder by double-clicking.
 177→   * Phase 6.3: Uses breadcrumb path to verify navigation (~/root/foldername format).
 178→   */
 179→  async function navigateIntoFolder(name: string): Promise<void> {
 180→    // Retry once if navigation fails (transient IPNS resolution failures in CI
 181→    // cause the app to navigate back to parent; the folder row reappears and
 182→    // a second attempt usually succeeds).
 183→    for (let attempt = 0; attempt < 2; attempt++) {
 184→      await fileList.doubleClickFolder(name);
 185→      try {
 186→        await breadcrumbs.waitForPathToContain(name, { timeout: 30000 });
 187→        navigationStack.push(name);
 188→        return;
 189→      } catch {
 190→        if (attempt === 1) throw new Error(`navigateIntoFolder("${name}") failed after 2 attempts`);
 191→        // Wait for the app to settle after a failed navigation (it navigates back to parent)
 192→        await page.waitForTimeout(2000);
 193→        // Verify the folder row is still visible before retrying
 194→        await fileList.waitForItemToAppear(name, { timeout: 10000 });
 195→      }
 196→    }
 197→  }
 198→
 199→  /**
 200→   * Navigate back to parent folder.
 201→   * Phase 6.3: Uses [..] PARENT_DIR row instead of breadcrumb back button.
 202→   */
 203→  async function navigateBack(): Promise<void> {
 204→    await parentDir.click();
 205→    await page.waitForTimeout(500); // Wait for navigation
 206→    if (navigationStack.length > 1) {
 207→      navigationStack.pop();
 208→    }
 209→  }
 210→
 211→  /**
 212→   * Navigate to root folder.
 213→   * Phase 6.3: Uses ParentDirRow navigation repeatedly until at root.
 214→   * Note: Cannot use page.goto('/files') as it reloads the page and loses folder state.
 215→   */
 216→  async function navigateToRoot(): Promise<void> {
 217→    // Keep clicking [..] PARENT_DIR until we're at root (no more parent row)
 218→    const maxIterations = 10;
 219→    for (let i = 0; i < maxIterations; i++) {
 220→      const parentDirRow = page.locator('[data-testid="parent-dir-row"]');
 221→      const isVisible = await parentDirRow.isVisible().catch(() => false);
 222→
 223→      if (!isVisible) {
 224→        // No parent row means we're at root
 225→        break;
 226→      }
 227→
 228→      await parentDirRow.dblclick();
 229→      await page.waitForTimeout(300); // Wait for navigation
 230→    }
 231→
 232→    // Verify we're at root by checking breadcrumbs (new interactive format)
 233→    // At root, there's only one breadcrumb item: "my vault"
 234→    await page.locator('.breadcrumb-item', { hasText: /my vault/i }).waitFor({
 235→      state: 'visible',
 236→      timeout: 10000,
 237→    });
 238→
 239→    // Reset navigation stack to root
 240→    navigationStack.length = 0;
 241→    navigationStack.push('root');
 242→  }
