 244→  /**
 245→   * Upload a file and wait for it to appear in the list.
 246→   */
 247→  async function uploadFile(
 248→    fileName: string,
 249→    content: string
 250→  ): Promise<{ path: string; name: string }> {
 251→    const testFile = createTestTextFile(fileName, content);
 252→    await uploadZone.uploadFile(testFile.path);
 253→
 254→    // Wait for file to appear
 255→    const result = await Promise.race([
 256→      fileList.waitForItemToAppear(fileName, { timeout: 30000 }).then(() => 'success' as const),
 257→      page
 258→        .locator('.upload-zone-error, [role="alert"]')
 259→        .filter({ hasText: /could not be added/ })
 260→        .waitFor({ state: 'visible', timeout: 30000 })
 261→        .then(() => 'error' as const),
 262→    ]);
 263→
 264→    if (result === 'error') {
 265→      const errorText = await page.locator('[role="alert"]').textContent();
 266→      throw new Error(`Upload failed: ${errorText}`);
 267→    }
 268→
 269→    return testFile;
 270→  }
