 42→  /** Best-effort Zustand quota store accessor (returns null if store not exposed). */
 43→  type QuotaStore = { getState: () => { usedBytes: number } };
 44→  const getQuotaUsedBytes = (p: Page) =>
 45→    p.evaluate(() => {
 46→      try {
 47→        const store = (window as unknown as Record<string, Record<string, QuotaStore> | undefined>)
 48→          .__ZUSTAND_STORES__?.quota;
 49→        if (!store) return null;
 50→        return store.getState().usedBytes as number;
 51→      } catch {
 52→        return null;
 53→      }
 54→    });
