394→
395→    // Wait for IPNS publish to propagate
396→    await page.waitForTimeout(5000);
397→
398→    // 2. Overwrite fixture with larger content and re-upload same name
399→    const v2File = createTestTextFile(fileName, v2Content);
400→    await uploadZone.uploadFile(v2File.path);
401→
402→    // 3. ReplaceFileDialog should appear — click "Replace"
403→    const replaceButton = page.getByTestId('replace-file-confirm');
404→    await replaceButton.waitFor({ state: 'visible', timeout: 30000 });
405→    await replaceButton.click();
406→
407→    // 4. Wait for replace to complete (dialog dismisses, file still in list)
408→    await replaceButton.waitFor({ state: 'hidden', timeout: 30000 });
409→    await page.waitForTimeout(3000); // Wait for IPNS publish
410→
411→    // 5. Snapshot quota usage (best-effort)
412→    const quotaBefore = await getQuotaUsedBytes(page);
413→
414→    // 6. Soft-delete the file
415→    await fileList.rightClickItem(fileName);
416→    await contextMenu.waitForOpen();
417→    await contextMenu.clickDelete();
418→    await confirmDialog.waitForOpen();
419→    await confirmDialog.clickConfirm();
420→    await fileList.waitForItemToDisappear(fileName, { timeout: 30000 });
421→
422→    // 7. Navigate to bin and permanently delete
423→    await binPage.navigate();
424→    await binPage.waitForBinItem(fileName, { timeout: 30000 });
425→    await binPage.permanentlyDeleteItem(fileName);
426→
427→    // PRIMARY ASSERTION: permanent delete completes without crash
428→    await binPage.waitForBinItemToDisappear(fileName, { timeout: 30000 });
429→
430→    // SECONDARY ASSERTION (best-effort): quota reclaim covers more than just the
431→    // current content CID — proves versionCids cleanup also ran.
432→    // v2 content is 2048 bytes; if version CIDs (v1 = 1024 bytes) were also
433→    // reclaimed, the delta will exceed v2Content alone.
434→    if (quotaBefore !== null) {
435→      // Wait for quota to settle after unpinning
436→      await page.waitForTimeout(3000);
437→      const quotaAfter = await getQuotaUsedBytes(page);
438→      if (quotaAfter !== null) {
439→        const reclaimed = quotaBefore - quotaAfter;
440→        // Must reclaim more than just v2 content size — proves version CIDs were also freed
441→        expect(reclaimed).toBeGreaterThan(v2Content.length);
442→      }
443→    }
444→  });
445→});
