  1→import { Page } from '@playwright/test';
  2→import { initializeVault, encryptVaultKeys, decryptVaultKeys } from '@cipherbox/core';
  3→import { deriveIpnsName, hexToBytes, bytesToHex } from '@cipherbox/crypto';
  4→import * as ed from '@noble/ed25519';
  5→
  6→/**
  7→ * Test credentials from environment variables.
  8→ * These are loaded from .env locally or GitHub Secrets in CI.
  9→ *
 10→ * With Core Kit, the E2E flow uses CipherBox's own login UI:
 11→ * 1. Enter email in CipherBox email input
 12→ * 2. Backend sends OTP (static OTP in test mode)
 13→ * 3. Enter OTP code
 14→ * 4. CipherBox JWT -> Core Kit loginWithJWT -> backend auth -> vault init
 15→ */
 16→export const TEST_CREDENTIALS = {
 17→  email: process.env.WEB3AUTH_TEST_EMAIL || '',
 18→  otp: process.env.WEB3AUTH_TEST_OTP || '',
 19→};
 20→
 21→/**
 22→ * Serializable auth state for a test account.
 23→ * Arrays are used because Uint8Array can't cross the page.evaluate boundary.
 24→ *
 25→ * @security Contains raw ECDSA private key material (`privateKeyArr`).
 26→ * Never pass this object to console.log(), JSON.stringify(), or any
 27→ * persistent storage — treat it the same as a plaintext private key.
 28→ */
 29→export interface TestAuthState {
 30→  accessToken: string;
 31→  email: string;
 32→  publicKeyHex: string;
 33→  publicKeyArr: number[];
 34→  /** @security Raw ECDSA secp256k1 private key — never log or serialize. */
 35→  privateKeyArr: number[];
 36→  rootFolderKeyArr: number[];
 37→  rootIpnsPublicKeyArr: number[];
 38→  rootIpnsPrivateKeyArr: number[];
 39→  rootIpnsName: string;
 40→  vaultId: string;
 41→}
