 43→/**
 44→ * Cached auth state from test-login endpoint (singleton for backward compat).
 45→ * Used to re-inject state after page reload (since test-login bypasses
 46→ * Core Kit, there's no persistent session to restore from).
 47→ */
 48→let cachedTestAuthState: TestAuthState | null = null;
 49→
 50→/**
 51→ * Performs email login through CipherBox's custom login UI.
 52→ *
 53→ * When TEST_LOGIN_SECRET is set, uses the /auth/test-login endpoint to bypass
 54→ * Core Kit entirely. This decouples E2E tests from Web3Auth infrastructure.
 55→ *
 56→ * Otherwise falls back to the full Core Kit flow through CipherBox's login UI.
 57→ *
 58→ * @param page - Playwright page instance
 59→ * @param email - Email address for login
 60→ * @param otp - Optional OTP code (defaults to TEST_CREDENTIALS.otp)
 61→ */
 62→export async function loginViaEmail(page: Page, email: string, otp?: string): Promise<void> {
 63→  // Use test-login endpoint when available (bypasses Core Kit completely)
 64→  if (process.env.TEST_LOGIN_SECRET) {
 65→    const state = await loginViaTestEndpoint(page, email);
 66→    cachedTestAuthState = state;
 67→    return;
 68→  }
 69→
 70→  const otpCode = otp || TEST_CREDENTIALS.otp;
 71→
 72→  // Navigate to login page
 73→  await page.goto('/');
 74→
 75→  // Step 1: Enter email in CipherBox's own email input
 76→  const emailInput = page.locator('[data-testid="email-input"]');
 77→  await emailInput.waitFor({ state: 'visible', timeout: 15000 });
 78→  await emailInput.fill(email);
 79→
 80→  // Step 2: Click [SEND OTP] button
 81→  const sendOtpButton = page.locator('[data-testid="send-otp-button"]');
 82→  await sendOtpButton.click();
 83→
 84→  // Step 3: Wait for OTP input to appear (backend sends OTP, form transitions)
 85→  const otpInput = page.locator('[data-testid="otp-input"]');
 86→  await otpInput.waitFor({ state: 'visible', timeout: 15000 });
 87→
 88→  // Step 4: Enter the test OTP code
 89→  await otpInput.fill(otpCode);
 90→
 91→  // Step 5: Click [VERIFY] button
 92→  const verifyButton = page.locator('[data-testid="verify-button"]');
 93→  await verifyButton.click();
 94→
 95→  // Step 6: Wait for login to complete and redirect to files page
 96→  // Core Kit loginWithJWT + backend auth + vault init can take time
 97→  await page.waitForURL('**/files', { timeout: 60000 });
 98→}
