226→/**
227→ * Inject auth state into Zustand stores on a page.
228→ * Works with both the singleton cache (backward compat) and explicit state (multi-account).
229→ */
230→export async function injectAuthState(page: Page, state: TestAuthState): Promise<void> {
231→  // Wait for the app to load and expose stores (dev mode only)
232→  await page.waitForFunction(
233→    () => !!(window as unknown as Record<string, unknown>).__ZUSTAND_STORES,
234→    {
235→      timeout: 15000,
236→    }
237→  );
238→
239→  // Inject auth + vault state into Zustand stores
240→  // Arrays are used because Uint8Array can't be serialized across page.evaluate boundary
241→  await page.evaluate((data) => {
242→    const stores = (window as unknown as Record<string, unknown>).__ZUSTAND_STORES as {
243→      auth: { setState: (s: Record<string, unknown>) => void };
244→      vault: { getState: () => { setVaultKeys: (k: Record<string, unknown>) => void } };
245→    };
246→
247→    stores.auth.setState({
248→      accessToken: data.accessToken,
249→      isAuthenticated: true,
250→      lastAuthMethod: 'email_passwordless',
251→      userEmail: data.email,
252→      vaultKeypair: {
253→        publicKey: new Uint8Array(data.publicKeyArr),
254→        privateKey: new Uint8Array(data.privateKeyArr),
255→      },
256→    });
257→
258→    stores.vault.getState().setVaultKeys({
259→      rootFolderKey: new Uint8Array(data.rootFolderKeyArr),
260→      rootIpnsKeypair: {
261→        publicKey: new Uint8Array(data.rootIpnsPublicKeyArr),
262→        privateKey: new Uint8Array(data.rootIpnsPrivateKeyArr),
263→      },
264→      rootIpnsName: data.rootIpnsName,
265→      vaultId: data.vaultId,
266→    });
267→  }, state);
268→}
