320→/**
321→ * Waits for the user to be authenticated by checking for auth indicators.
322→ * This is useful after manual login or when loading storage state.
323→ */
324→export async function waitForAuthentication(page: Page): Promise<void> {
325→  // Wait for user menu to appear (indicator of authenticated state)
326→  // Phase 6.3: Logout moved to UserMenu dropdown
327→  await page.waitForSelector('[data-testid="user-menu"]', { timeout: 15000 });
328→}
