330→/**
331→ * Extract the 0x04-prefixed public key hex from a TestAuthState.
332→ * This is the format needed for the ShareDialog recipient input.
333→ * The test-login endpoint returns bare hex (04...) so we prepend 0x.
334→ */
335→export function getPublicKeyHex(state: TestAuthState): string {
336→  return state.publicKeyHex.startsWith('0x') ? state.publicKeyHex : '0x' + state.publicKeyHex;
337→}
