    await account.page.evaluate(() => {
      window.location.hash = '#/shared';
    });
    await account.page.waitForURL('**/shared', { timeout: 30000 });
  }
  await account.page.evaluate(() => {
    window.location.hash = '#/files';
  });
  await account.page.waitForURL('**/files', { timeout: 30000 });
}

